 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = []

    # A colored plus is a nonzero, non-marker center with four orthogonal 3s.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = grid[r][c]
            if color not in (0, 3) and all(
                grid[nr][nc] == 3
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
            ):
                centers.append((r, c, color))

    def ray(r, c, dr, dc, color):
        # Extend through the source's adjacent 3 arm. Stop at the next 3 marker,
        # which marks another plus/obstacle; retain all marker cells.
        rr, cc = r + dr, c + dc
        first = True
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == 3:
                if first:
                    first = False
                    rr += dr
                    cc += dc
                    continue
                break
            first = False
            out[rr][cc] = color
            rr += dr
            cc += dc

    # Beams crossing at overlaps take the vertical beam's color.
    for r, c, color in centers:
        ray(r, c, 0, -1, color)
        ray(r, c, 0, 1, color)
    for r, c, color in centers:
        ray(r, c, -1, 0, color)
        ray(r, c, 1, 0, color)
    return out
